    },
    {
      "decision": "objective_definition",
      "evidence": "\"Your salary is based on division profit, so you try to maximize the profit.\"",
      "options": [
        "maximize contribution margin (revenue minus cereal, meat, and blending/packing costs)",
        "maximize revenue only (ignore ingredient and processing costs)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "maximize contribution margin (revenue minus cereal, meat, and blending/packing costs)"
    },
    {
      "decision": "resource_cost_treatment",
      "evidence": "\"up to 400,000 pounds of cereal each month at $0.20 per pound\" / \"up to 300,000 pounds of meat per month at $0.50 per pound\"",
      "options": [
        "charge ingredient cost per pound actually used (linear variable cost)",
        "treat ingredient costs as sunk/fixed and exclude them from the objective"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "charge ingredient cost per pound actually used (linear variable cost)"
    },
    {
      "decision": "machine_capacity_encoding",
      "evidence": "\"a special piece of machinery is required to make Meaties, and this machine has a capacity of 90,000 packages per month\"",
      "options": [
        "upper bound x_Meaties <= 90000 (as a variable bound and/or explicit constraint)",
        "no explicit machine constraint (rely on other limits)"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "upper bound x_Meaties <= 90000 (as a variable bound and/or explicit constraint)"
    },
    {
      "decision": "resource_limit_direction",
      "evidence": "\"can buy only up to 400,000 pounds of cereal\" / \"can buy only up to 300,000 pounds of meat\"",
      "options": [
        "cereal and meat usage <= availability (<=)",
        "cereal and meat usage = availability (=)"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "cereal and meat usage <= availability (<=)"
    },
    {
      "decision": "yummies_upper_bound",
      "evidence": "\"Healthy believes it can sell as much of each dog food as it can make.\"",
      "options": [
        "no upper bound on Yummies (only resource limits)",
        "impose an artificial sales cap on Yummies"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "no upper bound on Yummies (only resource limits)"
    }
  ]
